SELECT movement_id, product_id, product_name, scrap_quantity, loss_amount, occurred_at
FROM agent_v3_inventory_scrap_view WHERE agent_v3_inventory_scrap_view.store_id = ANY(:allowedStoreIds) AND agent_v3_inventory_scrap_view.occurred_at >= :startAt AND agent_v3_inventory_scrap_view.occurred_at < :endAt ORDER BY occurred_at DESC
LIMIT 100;

SELECT activity_id, activity_title, status, publish_status, start_at, end_at, participants, conversion
FROM agent_v3_marketing_activity_view
WHERE agent_v3_marketing_activity_view.store_id = ANY(:allowedStoreIds) AND (status IN ('***', '***', '***', '***')) LIMIT 100;
